        description: Checkout Default Repository
triggers:
  - bitbucket-server-trigger
  - tag

branch-overrides:
  - master:
      stages:
        - Default Stage:
            jobs:
              - Default Job
        - Publish Master:
            manual: true
            jobs:
              - Publish Master Job

      Publish Master Job:
        tasks:
          - checkout:
              description: Checkout code for publish on the master
              force-clean-build: true

        requirements:
          - centos: '9'
          - Docker

        other:
          clean-working-dir: true

